oxy_webhelp_navlinks = {"k8s_application_protection_set-d39307e27242":{"topics":[{"title":"Namespace patterns and dependency traversal","shortdesc":"<p class=\"shortdesc\">Application protection sets use namespace patterns to define scope and filters to         identify entry-point workloads. Rubrik automatically captures dependency resources linked to         matched workloads.<\/p>","href":"kubernetes\/k8s_application_ps_namespace_patterns.html","attributes":{"data-id":"k8s_application_ps_namespace_patterns"},"menu":{"hasChildren":false},"tocID":"k8s_application_ps_namespace_patterns-d39307e27253","topics":[]},{"title":"Creating an application protection set","shortdesc":"<p class=\"shortdesc\">Create an application protection set to protect workloads that span multiple         Kubernetes namespaces as a single unit.<\/p>","href":"kubernetes\/k8s_creating_application_protection_set.html","attributes":{"data-id":"k8s_creating_application_protection_set"},"menu":{"hasChildren":false},"tocID":"k8s_creating_application_protection_set-d39307e27264","topics":[]},{"title":"ApplicationProtectionSet Custom Resource Definition","shortdesc":"<p class=\"shortdesc\">The <code class=\"ph codeph\">ApplicationProtectionSet<\/code> custom resource definition enables you         to create and manage an application protection set using Kubernetes-native tools such as         kubectl.<\/p>","href":"kubernetes\/k8s_application_protectionset_crd.html","attributes":{"data-id":"k8s_application_protectionset_crd"},"menu":{"hasChildren":false},"tocID":"k8s_application_protectionset_crd-d39307e27275","topics":[]}]}};